update public.learning_paths
set
  title = 'Music History I (Medieval-Baroque)',
  goal = 'Music History I (Medieval-Baroque)',
  summary = 'Music History I surveys music from medieval chant through the high Baroque, emphasizing how repertories were made, notated, performed, circulated, heard, and remembered. Students study chant, early polyphony, medieval secular song, Renaissance sacred and secular music, the rise of opera, Baroque style, Bach, Handel, instrumental forms, and performance practice. The course pairs listening and score study with primary sources, visual/material culture, and historiographical questions so students learn to hear style and think historically.',
  data = $mh1json${"slug": "music-history-i-medieval-baroque", "title": "Music History I (Medieval-Baroque)", "description": "Music History I surveys music from medieval chant through the high Baroque, emphasizing how repertories were made, notated, performed, circulated, heard, and remembered. Students study chant, early polyphony, medieval secular song, Renaissance sacred and secular music, the rise of opera, Baroque style, Bach, Handel, instrumental forms, and performance practice. The course pairs listening and score study with primary sources, visual/material culture, and historiographical questions so students learn to hear style and think historically.", "topics": [{"id": "7f8c6f78-86c3-40a9-847a-750576dbcc3c", "type": "topic", "title": "Gregorian Chant and Early Polyphony", "description": "This opening unit introduces music as liturgy, memory, notation, and institution. Students learn how chant became a foundation for Western notation and polyphonic thinking.", "children": [{"id": "507f7ca9-fa76-49db-98de-db16f50b6273", "type": "subtopic", "title": "Chant, Liturgy, and Mode", "children": [{"id": "cb87d2dc-3646-4be8-8c71-82506eb322c7", "type": "concept", "title": "Mass and Office"}, {"id": "df089425-02d7-4117-860d-a86b63c4e860", "type": "concept", "title": "Psalm tones, antiphons, responsories, sequences"}, {"id": "b4aae741-cffb-4953-af0c-44d4c518ef6b", "type": "concept", "title": "Church modes and melodic contour"}], "description": "Students learn the sound-world and function of plainchant."}, {"id": "77891987-0777-4671-9887-afdecbc3832c", "type": "subtopic", "title": "Notation and Manuscripts", "children": [{"id": "7ce91fcf-a62c-4ff6-b234-79b3405cf24f", "type": "concept", "title": "Neumes, staff notation, solmization"}, {"id": "15d934e9-ddd5-4c53-8910-9bc1da173fc3", "type": "concept", "title": "Manuscript layout and scribal practice"}, {"id": "220addda-e1f1-491e-b8f7-4a70c685113c", "type": "concept", "title": "What notation preserves and what it omits"}], "description": "The point is to see notation as historical technology, not neutral transcription."}, {"id": "4468da0b-2ea2-4eb5-a6f4-3109f88754d0", "type": "subtopic", "title": "Early Polyphony", "children": [{"id": "4b35b94f-ff08-4e2f-847c-784fac17c713", "type": "concept", "title": "Parallel and free organum"}, {"id": "0b2bdea1-44d0-4919-b401-20f5bf485aa5", "type": "concept", "title": "Notre Dame organum and clausula"}, {"id": "92cadaa0-d7a2-42c6-9d5d-7ac32274d002", "type": "concept", "title": "Conductus, motet, rhythmic modes"}], "description": "Students trace the move from single line to coordinated voices."}]}, {"id": "10097a2c-3077-48e4-8fec-569966452c3d", "type": "topic", "title": "Medieval Secular Music", "description": "Medieval musical life was not only sacred. Court, city, dance, poetry, and vernacular song reveal other institutions and audiences.", "children": [{"id": "7af265c5-e56e-4d51-8a68-c80a605764dd", "type": "subtopic", "title": "Courtly Song Traditions", "children": [{"id": "8c908fcd-884a-480e-af0d-54067555b8e8", "type": "concept", "title": "Troubadours and trouveres"}, {"id": "b498525a-b540-4326-ad09-120e90706db4", "type": "concept", "title": "Minnesang"}, {"id": "dd5c3b87-6d53-42fb-ae98-52b65069f04e", "type": "concept", "title": "Fin'amor, patronage, gender, and status"}], "description": "Students study song as poetry, performance, and social code."}, {"id": "d43c91bc-ccd8-4f06-8d9d-4cc3a0ef0f31", "type": "subtopic", "title": "Dance and Urban Music", "children": [{"id": "7ba548c2-d114-4449-98ed-52210767fd47", "type": "concept", "title": "Estampie and dance forms"}, {"id": "6b9589b0-f381-4c83-8b01-ae85ca970ce8", "type": "concept", "title": "Minstrels, guilds, and civic ceremony"}, {"id": "3b282a2b-e990-4bdb-a4f7-361aea939b6a", "type": "concept", "title": "Orality and reconstruction problems"}], "description": "The unit broadens beyond elite manuscripts."}, {"id": "66693398-ecc7-49be-a488-34269a9e21ca", "type": "subtopic", "title": "Ars Nova and Formes Fixes", "children": [{"id": "150339e1-193c-4969-9abe-35794d4d9616", "type": "concept", "title": "Machaut"}, {"id": "3e1a77ad-734a-4882-9dfd-36d6db2cd986", "type": "concept", "title": "Ballade, rondeau, virelai"}, {"id": "5360336c-02a7-4ee9-9784-a20583cbff2b", "type": "concept", "title": "Isorhythm and mensural notation"}], "description": "Students encounter rhythmic and notational sophistication."}]}, {"id": "92b86d06-c5b8-4714-a909-2d6dd0700636", "type": "topic", "title": "Renaissance Sacred Music", "description": "Renaissance sacred music develops imitative counterpoint, humanist clarity, and institutional power across church, court, chapel, and print.", "children": [{"id": "cf0bf107-0087-4418-bba2-2c2fff3010e1", "type": "subtopic", "title": "Mass and Motet", "children": [{"id": "32f8fc97-6a29-4fb5-9dc2-5ef91f1ac21b", "type": "concept", "title": "Cyclic mass, cantus firmus mass, parody mass"}, {"id": "c692795f-8a19-4bc5-8402-86f27c7f4a2c", "type": "concept", "title": "Motet text setting"}, {"id": "90d58fe7-2179-4c50-ad32-c5ffd5d9b9de", "type": "concept", "title": "Cantus firmus and imitation"}], "description": "Students learn major sacred genres and their formal designs."}, {"id": "be79a2c3-1f52-4a2c-95a2-5daf7e39991b", "type": "subtopic", "title": "Composers and Institutions", "children": [{"id": "15e65c9f-921c-4031-9d57-ed8f5c16ed6c", "type": "concept", "title": "Dufay, Josquin, Palestrina, Byrd, Victoria"}, {"id": "882aa9f9-a50b-4c47-a4a5-5d920db46419", "type": "concept", "title": "Papal chapel, courts, cathedrals"}, {"id": "129563d6-905f-475f-a376-ce36ec98857b", "type": "concept", "title": "Reformation and Counter-Reformation debates"}], "description": "Style is tied to chapels, patrons, and confessional politics."}, {"id": "7d92a6e4-94dc-41e3-a637-de071e10c0b4", "type": "subtopic", "title": "Texture and Text", "children": [{"id": "bdc1daca-737b-4875-9e09-a2a0196df62d", "type": "concept", "title": "Imitative points"}, {"id": "a55c8dd9-b583-4710-b388-5e30aa2cc7cc", "type": "concept", "title": "Cadences and modal goals"}, {"id": "84d04d1c-0267-4a07-a9c9-5cf3f3b9fa18", "type": "concept", "title": "Text clarity, melisma, and homophony"}], "description": "Students learn to hear how polyphony projects meaning."}]}, {"id": "04730f1e-1d47-46bf-9f55-54e047e24c44", "type": "topic", "title": "Renaissance Secular Music: Madrigal and Beyond", "description": "Secular Renaissance repertories show the rise of print culture, vernacular expression, domestic music-making, and text-driven composition.", "children": [{"id": "3816f3c0-7cc4-4402-8a2f-5b67ca8ac0e0", "type": "subtopic", "title": "Madrigal", "children": [{"id": "d22c42b2-1856-49c5-a1da-1c4b322e6471", "type": "concept", "title": "Italian madrigal"}, {"id": "9a67dcce-37b4-4eae-b337-1ef52c534d53", "type": "concept", "title": "English madrigal"}, {"id": "371b32b5-56f8-429c-897f-32a13bc876fc", "type": "concept", "title": "Text expression, chromaticism, and affect"}], "description": "Students study the madrigal as a laboratory for word painting and expressive dissonance."}, {"id": "d6c91a37-422f-4170-8efa-155beb32beba", "type": "subtopic", "title": "Chanson, Frottola, and Lied", "children": [{"id": "4af86572-a1ff-4e4a-b89e-9044645afe5e", "type": "concept", "title": "Parisian chanson"}, {"id": "6c5b703c-14ab-41aa-8592-29818fd98406", "type": "concept", "title": "Frottola"}, {"id": "dceb24a9-8be3-43ea-81f3-03847c29bee7", "type": "concept", "title": "Tenorlied and vernacular repertory"}], "description": "The unit compares national and regional secular styles."}, {"id": "4ec49b4c-f0d1-4158-8f78-71b851c3d0b0", "type": "subtopic", "title": "Printing and Domestic Music", "children": [{"id": "5fdde11c-3e0f-4d85-8444-ee585a51964a", "type": "concept", "title": "Petrucci and music printing"}, {"id": "e25377df-6eac-4baa-b23e-83f88c78982a", "type": "concept", "title": "Partbooks"}, {"id": "c536f796-e1f5-411b-b84b-707eb64fb3b5", "type": "concept", "title": "Courtly and domestic audiences"}], "description": "Students connect repertoire to media and amateur performance."}]}, {"id": "b2f84782-fcb3-4f34-9aaa-445d7b75c14d", "type": "topic", "title": "The Rise of Opera", "description": "Opera emerges from humanism, theater, monody, patronage, and experiments in representing speech, affect, and drama through music.", "children": [{"id": "762a8a86-27ac-49b4-8bc2-1372690e0acf", "type": "subtopic", "title": "Florentine and Mantuan Contexts", "children": [{"id": "eb954023-bffa-478e-9581-a6c35299524f", "type": "concept", "title": "Camerata and humanism"}, {"id": "b2a066d4-3e77-4c0b-a6b3-7e74cdf2b165", "type": "concept", "title": "Court spectacle"}, {"id": "b6e77363-4fe4-4a12-8d6e-cdf7d73aeca9", "type": "concept", "title": "Monteverdi and early public opera"}], "description": "Students learn why opera appears when and where it does."}, {"id": "b201f214-e75f-43d9-a421-3ab1a7b4a751", "type": "subtopic", "title": "Recitative, Aria, and Dramatic Time", "children": [{"id": "329f8e52-815f-47d5-ab71-905c931fa1e6", "type": "concept", "title": "Monody and basso continuo"}, {"id": "3b159caa-dc46-4af6-a40a-624d6d8838a8", "type": "concept", "title": "Recitative styles"}, {"id": "6c572ee2-d0a6-4be6-9ea8-be77dfc12a92", "type": "concept", "title": "Lament, aria, chorus, and ritornello"}], "description": "The unit shows how music organizes action."}, {"id": "c0127751-2a68-4b64-9d42-4c690370369b", "type": "subtopic", "title": "Opera as Institution", "children": [{"id": "688953aa-44b2-4b0c-b5ad-1964ac2cb81b", "type": "concept", "title": "Court opera and public theaters"}, {"id": "9f5723ad-dbc5-4540-a549-fe1926dc3ee7", "type": "concept", "title": "Singers, impresarios, and patrons"}, {"id": "23f87824-3e76-4925-acca-6ee5a114b74c", "type": "concept", "title": "Gender, spectacle, and audience"}], "description": "Students connect genre to economics and power."}]}, {"id": "4db57438-6d0c-4294-b0b4-2bdc4fb3a44f", "type": "topic", "title": "Baroque Style and Basso Continuo", "description": "Baroque style centers contrast, affect, bass-line thinking, continuo practice, and increasingly idiomatic instrumental writing.", "children": [{"id": "d75da212-5aca-41ef-98f0-075f85c91fdb", "type": "subtopic", "title": "Basso Continuo", "children": [{"id": "e2183248-cec4-4346-9e80-aeb37a1dce18", "type": "concept", "title": "Figured bass"}, {"id": "d581f4cb-ef24-4065-bebc-b7912360bd5b", "type": "concept", "title": "Harpsichord, organ, lute, theorbo, cello, bass viol"}, {"id": "ab692d7b-5994-4185-8f57-546cf4b112fb", "type": "concept", "title": "Realization and improvisation"}], "description": "Students learn continuo as harmonic foundation and performance practice."}, {"id": "d90f0f87-987d-426d-96b5-ed0293677456", "type": "subtopic", "title": "Affect and Rhetoric", "children": [{"id": "fa7cfcd6-ea2e-4f19-93fb-cc079e75037b", "type": "concept", "title": "Doctrine of affections"}, {"id": "3b20ba51-6047-4d7f-bf1f-6e7fb9f0c55d", "type": "concept", "title": "Musical-rhetorical figures"}, {"id": "3e114d32-c504-4d8f-b3c4-2765d4e8abf4", "type": "concept", "title": "Contrast, sequence, and drive"}], "description": "The Baroque links musical gesture to persuasion and emotion."}, {"id": "ecfc0725-3b51-49bf-b265-d98d037f80ec", "type": "subtopic", "title": "Concertato and Texture", "children": [{"id": "557c47e2-3dda-4c52-9707-125d0db7d4d8", "type": "concept", "title": "Solo/tutti contrast"}, {"id": "25a08616-a4cb-47a2-855e-9fdd7c748069", "type": "concept", "title": "Concertato sacred music"}, {"id": "bbd916e3-1123-4cb6-a0a9-7cf68d378d55", "type": "concept", "title": "Texture, register, and timbre"}], "description": "Students hear new relationships between forces."}]}, {"id": "d5e5b3c0-1d0e-49a9-a173-296b41480cfe", "type": "topic", "title": "Bach and the High Baroque", "description": "Bach synthesizes contrapuntal craft, Lutheran theology, dance, rhetoric, keyboard writing, and international styles.", "children": [{"id": "5752a0f6-cfb6-4fa9-a907-bdf1ede73b96", "type": "subtopic", "title": "Sacred Vocal Works", "children": [{"id": "d9f183dc-e01d-49a2-9a15-b75e930a553c", "type": "concept", "title": "Cantata, passion, chorale, recitative, aria"}, {"id": "8ae283a0-7fad-45c4-8192-85c2f77fcc6e", "type": "concept", "title": "Chorale theology and congregational memory"}, {"id": "65ac2b1a-557a-4ed1-b631-a32aa81964ae", "type": "concept", "title": "Text-music relationships"}], "description": "Students study Bach as liturgical composer and dramatist."}, {"id": "40e28473-c460-4cac-b82b-c224fad3bbd2", "type": "subtopic", "title": "Instrumental and Keyboard Works", "children": [{"id": "7fb98300-c216-4c50-81a9-c0c68a69b07d", "type": "concept", "title": "Invention, fugue, suite, concerto, toccata"}, {"id": "0fe89ba1-3afc-4855-b8b2-9da54e384950", "type": "concept", "title": "Motivic economy"}, {"id": "043ef650-ad37-4b8c-b0c3-e622b7625de1", "type": "concept", "title": "Dance and contrapuntal design"}], "description": "The unit links counterpoint to form and affect."}, {"id": "45f5645a-3cf1-45c1-80a0-9aa063a10608", "type": "subtopic", "title": "Historiography of Bach", "children": [{"id": "99d52252-e803-4f12-819c-3e8ab16110f6", "type": "concept", "title": "Reception history"}, {"id": "94c303b0-a6be-476a-9e29-3f44788e13e0", "type": "concept", "title": "Revival and editions"}, {"id": "63ef8f86-3702-4c81-af41-dfaa81e599bb", "type": "concept", "title": "Canon formation and pedagogy"}], "description": "Students ask how Bach became central to the canon."}]}, {"id": "7b730085-7430-4815-92d2-0b9ae5dbec9f", "type": "topic", "title": "Handel and Oratorio", "description": "Handel's career connects opera, oratorio, public concert culture, London commerce, and sacred drama outside the staged opera house.", "children": [{"id": "696354a4-f2e2-404c-9929-46c70f79f930", "type": "subtopic", "title": "Opera Seria and London", "children": [{"id": "31075eb4-1cd1-477f-a9ff-0a09023f28a4", "type": "concept", "title": "Da capo aria"}, {"id": "7b22a81f-f9e6-4d52-91a5-d1897550ea52", "type": "co